//! Embedded deployment templates and their rendering (spec #583, issue 1262;
//! ADRs 0049, 0057, 0087, 0090, 0126).
//!
//! Each executable embeds only its own Product's zstd-compressed deployment
//! templates (generated by `xtask codegen` from `packaging/deploy/` and
//! `packaging/oci/seccomp-profile.json`). Rendering calls the same pure
//! [`goodfetch_protocol::deploy::render`] function that `xtask`'s docs
//! generator and smoke-job renderer call; inside an executable the Product is
//! fixed to the running executable's bundle, never an argument.

use std::io;

use goodfetch_protocol::catalog::Product;
use goodfetch_protocol::connection::ProductVersion;
use goodfetch_protocol::deploy::{
    DeployImagePin, DeployRenderError, DeployTarget, DeployTemplateFile, RenderedDeployFile,
    render as render_protocol,
};
use goodfetch_protocol::starters::StarterLanguage;

/// One zstd-compressed deployment template file an executable embeds.
#[derive(Clone, Copy, Debug)]
pub struct DeployFile {
    /// The deployment target this file belongs to.
    pub target: DeployTarget,
    /// Its `/`-separated output path relative to the target folder.
    pub path: &'static str,
    /// The zstd-compressed template bytes.
    pub zstd_contents: &'static [u8],
}

/// The deployment templates an executable embeds, which `init --deploy` renders
/// offline at the executable's own Product and version.
#[derive(Clone, Copy, Debug)]
pub struct DeployTemplates {
    product: Product,
    repository: &'static str,
    default_digest: &'static str,
    nightly_digest: &'static str,
    files: &'static [DeployFile],
}

/// Why rendering an embedded deployment template failed.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum DeployTemplateError {
    /// Decompressing an embedded zstd template failed.
    #[error("embedded deployment template `{path}` could not be decompressed: {source}")]
    Decompress {
        /// The output path of the corrupted template.
        path: &'static str,
        /// The underlying zstd decoding error.
        #[source]
        source: io::Error,
    },
    /// Rendering the decompressed templates failed.
    #[error(transparent)]
    Render(#[from] DeployRenderError),
}

impl DeployTemplates {
    /// Collie's executable's embedded deployment templates.
    pub const COLLIE: Self = include!("../generated/deploy.rs");

    /// Builds a Product's embedded deployment template set.
    #[must_use]
    pub const fn new(
        product: Product,
        repository: &'static str,
        default_digest: &'static str,
        nightly_digest: &'static str,
        files: &'static [DeployFile],
    ) -> Self {
        Self {
            product,
            repository,
            default_digest,
            nightly_digest,
            files,
        }
    }

    /// The embedded files carried by this bundle.
    #[must_use]
    pub const fn files(self) -> &'static [DeployFile] {
        self.files
    }

    /// Renders `target` for `language` and `product_version` using this
    /// executable's own Product (never passed as an argument).
    ///
    /// # Errors
    ///
    /// Returns [`DeployTemplateError::Decompress`] if an embedded zstd stream
    /// cannot be decoded, or [`DeployTemplateError::Render`] if rendering
    /// fails.
    pub fn render(
        self,
        target: DeployTarget,
        language: Option<StarterLanguage>,
        product_version: &ProductVersion,
    ) -> Result<Vec<RenderedDeployFile>, DeployTemplateError> {
        let mut decoded: Vec<(&'static str, Vec<u8>)> = Vec::new();
        for file in self.files {
            if file.target != target {
                continue;
            }
            let bytes = zstd::stream::decode_all(file.zstd_contents).map_err(|source| {
                DeployTemplateError::Decompress {
                    path: file.path,
                    source,
                }
            })?;
            decoded.push((file.path, bytes));
        }
        let sources: Vec<DeployTemplateFile<'_>> = decoded
            .iter()
            .map(|(path, bytes)| DeployTemplateFile {
                path,
                contents: bytes.as_slice(),
            })
            .collect();
        let pin = DeployImagePin {
            repository: self.repository.to_owned(),
            default_digest: self.default_digest.to_owned(),
            nightly_digest: self.nightly_digest.to_owned(),
        };
        Ok(render_protocol(
            &sources,
            target,
            language,
            self.product,
            product_version,
            &pin,
        )?)
    }
}

#[cfg(test)]
mod tests {
    use goodfetch_protocol::connection::ProductVersion;
    use goodfetch_protocol::deploy::DeployTarget;

    use super::DeployTemplates;

    /// Covers: story:13-10, story:13-11
    #[test]
    fn collie_embeds_compressed_compose_templates_that_render_offline() {
        let compressed_bytes: usize = DeployTemplates::COLLIE
            .files()
            .iter()
            .map(|f| f.zstd_contents.len())
            .sum();
        // Templates are stored zstd-compressed and stay tiny well under the
        // +1 MB increase check and 8 MiB tarball ceiling (ADR 0057).
        assert!(
            compressed_bytes > 0 && compressed_bytes < 64 * 1024,
            "unexpected compressed deploy templates size: {compressed_bytes} bytes"
        );

        let version = ProductVersion::parse("1.2.3").unwrap();
        let files = DeployTemplates::COLLIE
            .render(DeployTarget::Compose, None, &version)
            .unwrap();
        let paths: Vec<&str> = files.iter().map(|f| f.path.as_str()).collect();
        assert_eq!(
            paths,
            vec![
                "compose.yaml",
                "operator-policy.toml",
                "seccomp-profile.json"
            ]
        );
        let compose = std::str::from_utf8(&files[0].contents).unwrap();
        assert!(compose.contains("ghcr.io/goodfetch/collie:1.2.3@sha256:"));
        assert!(!compose.contains(":latest"));
        assert!(compose.contains("goodfetch-collie"));

        let nightly = ProductVersion::parse("1.3.0-nightly.20261127").unwrap();
        let nightly_files = DeployTemplates::COLLIE
            .render(DeployTarget::Compose, None, &nightly)
            .unwrap();
        let nightly_compose = std::str::from_utf8(&nightly_files[0].contents).unwrap();
        assert!(nightly_compose.contains("ghcr.io/goodfetch/collie:nightly@sha256:"));
        assert!(!nightly_compose.contains(":latest"));
    }
}
